import { AbstractSocialCue } from './SocialCue.js';
export class HappinessCue extends AbstractSocialCue {
    start() {
        this.animationManager.scheduleChange("12", 100, 0.5, 0);
        this.animationManager.scheduleChange("6", 50, 0.5, 100);
        this.animationManager.scheduleChange("7", 50, 0.5, 100);
    }

    stop() {
        this.animationManager.scheduleChange("12", 0, 0.5, 0);
        this.animationManager.scheduleChange("6", 0, 0.5, 100);
        this.animationManager.scheduleChange("7", 0, 0.5, 100);
    }
}
